import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_ops_kernel(const float* input, float* output, int num_elements, float add_value, float multiply_value) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        val += add_value;
        val = fminf(val, 0.0f);
        float gelu = 0.5f * val * (1.0f + tanhf(0.7978845608028654f * (val + 0.044715f * val * val * val)));
        output[idx] = gelu * multiply_value;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor input, float add_value, float multiply_value) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();
    int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;
    fused_ops_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), num_elements, add_value, multiply_value);
    return output;
}
"""

fused_ops_cpp = "torch::Tensor fused_ops_cuda(torch::Tensor input, float add_value, float multiply_value);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_source,
    functions=['fused_ops_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, add_value, multiply_value):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride)
        self.add_value = add_value
        self.multiply_value = multiply_value
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_ops.fused_ops_cuda(x, self.add_value, self.multiply_value)
        return x
